var tree = get_tree()
var scene = tree.current_scene
Engine.max_fps = 120
var set_vector = func(v: Vector2):
	for axis in [JOY_AXIS_RIGHT_X, JOY_AXIS_RIGHT_Y]:
		var event = InputEventJoypadMotion.new()
		event.device = 0
		event.axis = axis
		event.axis_value = v.x if axis == JOY_AXIS_RIGHT_X else v.y
		Input.parse_input_event(event)
var wait_frames = func(count: int):
	for frame in range(count):
		await tree.process_frame
set_vector.call(Vector2.ZERO)
await wait_frames.call(3)
var states = []
for repeated in [false,true,true]:
	var key = InputEventKey.new()
	key.keycode = KEY_TAB
	key.pressed = true
	key.echo = repeated
	Input.parse_input_event(key)
	await wait_frames.call(2)
	states.append({"echo":repeated,"mode":scene.mode,"hits":scene.discrim_hits,"total":scene.discrim_total})
var release = InputEventKey.new()
release.keycode = KEY_TAB
release.pressed = false
Input.parse_input_event(release)
return {"states":states,"scope":"One initial Tab keydown followed by OS-style key-repeat events"}
